import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor batchnorm2d_forward(torch::Tensor x,
                                   torch::Tensor weight,
                                   torch::Tensor bias,
                                   torch::Tensor running_mean,
                                   torch::Tensor running_var,
                                   bool training,
                                   double momentum,
                                   double eps);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
constexpr int64_t TILE_UNITS = 65536;
constexpr int RED_BLOCK_THREADS = 256;
constexpr int NORM_BLOCK_THREADS = 256;
// Stage 1: partial reduction (sum, sumsq) per channel over a tile of the (N,HW) space,
// accumulated via atomics into per-channel global accumulators. Splitting each channel
// into many tiles (instead of a single block per channel) allows the grid to have far
// more blocks than channels, so large tensors keep many SMs busy concurrently.
__global__ void bn_reduce_kernel(
    const float* __restrict__ X,
    int N, int C, int HW,
    int64_t total_units, bool use_vec4,
    float* __restrict__ sum_arr,
    float* __restrict__ sumsq_arr)
{
    const int c = blockIdx.x;
    const int tile = blockIdx.y;
    const int64_t start = (int64_t)tile * TILE_UNITS;
    const int64_t end = (start + TILE_UNITS < total_units) ? (start + TILE_UNITS) : total_units;
    if (start >= end) return;
    const int64_t channel_stride = (int64_t)C * (int64_t)HW;
    const float* __restrict__ Xc = X + (int64_t)c * HW;
    const int tid = threadIdx.x;
    const int nthreads = blockDim.x;
    const int64_t HW4 = HW / 4;
    float sum = 0.f, sumsq = 0.f;
    if (use_vec4) {
        int64_t idx = start + tid;
        while (idx < end) {
            int64_t n = idx / HW4;
            int64_t row_start = n * HW4;
            int64_t row_end = row_start + HW4;
            int64_t j = idx - row_start;
            const float4* __restrict__ row =
                reinterpret_cast<const float4*>(Xc + n * channel_stride);
            int64_t local_end = row_end < end ? row_end : end;
            int64_t local_end2 = local_end - (int64_t)nthreads;
            for (; idx < local_end2; idx += 2 * nthreads, j += 2 * nthreads) {
                float4 v4a = row[j];
                float4 v4b = row[j + nthreads];
                sum   += (v4a.x + v4a.y + v4a.z + v4a.w) + (v4b.x + v4b.y + v4b.z + v4b.w);
                sumsq += (v4a.x * v4a.x + v4a.y * v4a.y + v4a.z * v4a.z + v4a.w * v4a.w)
                       + (v4b.x * v4b.x + v4b.y * v4b.y + v4b.z * v4b.z + v4b.w * v4b.w);
            }
            for (; idx < local_end; idx += nthreads, j += nthreads) {
                float4 v4 = row[j];
                sum   += v4.x + v4.y + v4.z + v4.w;
                sumsq += v4.x * v4.x + v4.y * v4.y + v4.z * v4.z + v4.w * v4.w;
            }
        }
    } else {
        int64_t idx = start + tid;
        while (idx < end) {
            int64_t n = idx / HW;
            int64_t row_start = n * (int64_t)HW;
            int64_t row_end = row_start + HW;
            int64_t hw = idx - row_start;
            const float* __restrict__ row = Xc + n * channel_stride;
            int64_t local_end = row_end < end ? row_end : end;
            for (; idx < local_end; idx += nthreads, hw += nthreads) {
                float v = row[hw];
                sum   += v;
                sumsq += v * v;
            }
        }
    }
    unsigned mask = 0xffffffffu;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum   += __shfl_down_sync(mask, sum, offset);
        sumsq += __shfl_down_sync(mask, sumsq, offset);
    }
    __shared__ float s_sum[RED_BLOCK_THREADS / 32];
    __shared__ float s_sq[RED_BLOCK_THREADS / 32];
    const int warp_id = tid >> 5;
    const int lane_id = tid & 31;
    if (lane_id == 0) {
        s_sum[warp_id] = sum;
        s_sq[warp_id]  = sumsq;
    }
    __syncthreads();
    if (tid == 0) {
        const int nwarps = nthreads / 32;
        float tot_sum = 0.f, tot_sq = 0.f;
        #pragma unroll
        for (int i = 0; i < nwarps; ++i) {
            tot_sum += s_sum[i];
            tot_sq  += s_sq[i];
        }
        atomicAdd(&sum_arr[c], tot_sum);
        atomicAdd(&sumsq_arr[c], tot_sq);
    }
}
// Stage 2: finalize per-channel mean/var from global accumulators, update running stats.
__global__ void bn_finalize_kernel(
    const float* __restrict__ sum_arr,
    const float* __restrict__ sumsq_arr,
    float* __restrict__ running_mean,
    float* __restrict__ running_var,
    float* __restrict__ mean_out,
    float* __restrict__ var_out,
    int64_t total, float momentum, int C)
{
    int c = blockIdx.x * blockDim.x + threadIdx.x;
    if (c >= C) return;
    float m = sum_arr[c] / (float)total;
    float v = sumsq_arr[c] / (float)total - m * m;
    if (v < 0.f) v = 0.f;
    mean_out[c] = m;
    var_out[c]  = v;
    float unbiased_var = (total > 1) ? (v * (float)total / (float)(total - 1)) : v;
    float old_rm = running_mean[c];
    float old_rv = running_var[c];
    running_mean[c] = (1.f - momentum) * old_rm + momentum * m;
    running_var[c]  = (1.f - momentum) * old_rv + momentum * unbiased_var;
}
// Stage 3: tiled elementwise normalization write, many blocks per channel.
__global__ void bn_normalize_kernel(
    const float* __restrict__ X,
    float* __restrict__ Y,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    const float* __restrict__ mean_arr,
    const float* __restrict__ var_arr,
    int N, int C, int HW,
    int64_t total_units, bool use_vec4, float eps)
{
    const int c = blockIdx.x;
    const int tile = blockIdx.y;
    const int64_t start = (int64_t)tile * TILE_UNITS;
    const int64_t end = (start + TILE_UNITS < total_units) ? (start + TILE_UNITS) : total_units;
    if (start >= end) return;
    const int64_t channel_stride = (int64_t)C * (int64_t)HW;
    const float* __restrict__ Xc = X + (int64_t)c * HW;
    float* __restrict__ Yc = Y + (int64_t)c * HW;
    const float mean_f = mean_arr[c];
    const float var_f  = var_arr[c];
    const float inv_std = rsqrtf(var_f + eps);
    const float w = weight[c];
    const float b = bias[c];
    const int tid = threadIdx.x;
    const int nthreads = blockDim.x;
    const int64_t HW4 = HW / 4;
    if (use_vec4) {
        int64_t idx = start + tid;
        while (idx < end) {
            int64_t n = idx / HW4;
            int64_t row_start = n * HW4;
            int64_t row_end = row_start + HW4;
            int64_t j = idx - row_start;
            const float4* __restrict__ row_in =
                reinterpret_cast<const float4*>(Xc + n * channel_stride);
            float4* __restrict__ row_out =
                reinterpret_cast<float4*>(Yc + n * channel_stride);
            int64_t local_end = row_end < end ? row_end : end;
            int64_t local_end2 = local_end - (int64_t)nthreads;
            for (; idx < local_end2; idx += 2 * nthreads, j += 2 * nthreads) {
                float4 v4a = row_in[j];
                float4 v4b = row_in[j + nthreads];
                float4 y4a, y4b;
                y4a.x = (v4a.x - mean_f) * inv_std * w + b;
                y4a.y = (v4a.y - mean_f) * inv_std * w + b;
                y4a.z = (v4a.z - mean_f) * inv_std * w + b;
                y4a.w = (v4a.w - mean_f) * inv_std * w + b;
                y4b.x = (v4b.x - mean_f) * inv_std * w + b;
                y4b.y = (v4b.y - mean_f) * inv_std * w + b;
                y4b.z = (v4b.z - mean_f) * inv_std * w + b;
                y4b.w = (v4b.w - mean_f) * inv_std * w + b;
                row_out[j] = y4a;
                row_out[j + nthreads] = y4b;
            }
            for (; idx < local_end; idx += nthreads, j += nthreads) {
                float4 v4 = row_in[j];
                float4 y4;
                y4.x = (v4.x - mean_f) * inv_std * w + b;
                y4.y = (v4.y - mean_f) * inv_std * w + b;
                y4.z = (v4.z - mean_f) * inv_std * w + b;
                y4.w = (v4.w - mean_f) * inv_std * w + b;
                row_out[j] = y4;
            }
        }
    } else {
        int64_t idx = start + tid;
        while (idx < end) {
            int64_t n = idx / HW;
            int64_t row_start = n * (int64_t)HW;
            int64_t row_end = row_start + HW;
            int64_t hw = idx - row_start;
            const float* __restrict__ row_in = Xc + n * channel_stride;
            float* __restrict__ row_out = Yc + n * channel_stride;
            int64_t local_end = row_end < end ? row_end : end;
            for (; idx < local_end; idx += nthreads, hw += nthreads) {
                float v = row_in[hw];
                float y = (v - mean_f) * inv_std * w + b;
                row_out[hw] = y;
            }
        }
    }
}
torch::Tensor batchnorm2d_forward(torch::Tensor x,
                                   torch::Tensor weight,
                                   torch::Tensor bias,
                                   torch::Tensor running_mean,
                                   torch::Tensor running_var,
                                   bool training,
                                   double momentum,
                                   double eps) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(x.dim() == 4, "x must be 4D (N,C,H,W)");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    auto b_c = bias.contiguous();
    auto rm_c = running_mean.contiguous().to(torch::kFloat32);
    auto rv_c = running_var.contiguous().to(torch::kFloat32);
    int N = (int)x_c.size(0);
    int C = (int)x_c.size(1);
    int H = (int)x_c.size(2);
    int W = (int)x_c.size(3);
    int HW = H * W;
    auto y = torch::empty_like(x_c);
    const bool use_vec4 = (HW % 4 == 0);
    const int64_t total = (int64_t)N * (int64_t)HW;
    const int64_t total_units = use_vec4 ? (total / 4) : total;
    int64_t num_tiles64 = (total_units + TILE_UNITS - 1) / TILE_UNITS;
    if (num_tiles64 < 1) num_tiles64 = 1;
    const unsigned num_tiles = (unsigned)num_tiles64;
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    auto options_f = torch::TensorOptions().dtype(torch::kFloat32).device(x.device());
    torch::Tensor mean_arr, var_arr;
    if (training) {
        auto sum_arr   = torch::zeros({C}, options_f);
        auto sumsq_arr = torch::zeros({C}, options_f);
        mean_arr = torch::empty({C}, options_f);
        var_arr  = torch::empty({C}, options_f);
        dim3 grid1((unsigned)C, num_tiles);
        dim3 block1(RED_BLOCK_THREADS);
        bn_reduce_kernel<<<grid1, block1, 0, stream>>>(
            x_c.data_ptr<float>(), N, C, HW, total_units, use_vec4,
            sum_arr.data_ptr<float>(), sumsq_arr.data_ptr<float>());
        int fin_threads = 256;
        int fin_blocks = (C + fin_threads - 1) / fin_threads;
        bn_finalize_kernel<<<fin_blocks, fin_threads, 0, stream>>>(
            sum_arr.data_ptr<float>(), sumsq_arr.data_ptr<float>(),
            rm_c.data_ptr<float>(), rv_c.data_ptr<float>(),
            mean_arr.data_ptr<float>(), var_arr.data_ptr<float>(),
            total, (float)momentum, C);
    } else {
        mean_arr = rm_c;
        var_arr  = rv_c;
    }
    dim3 grid3((unsigned)C, num_tiles);
    dim3 block3(NORM_BLOCK_THREADS);
    bn_normalize_kernel<<<grid3, block3, 0, stream>>>(
        x_c.data_ptr<float>(), y.data_ptr<float>(),
        w_c.data_ptr<float>(), b_c.data_ptr<float>(),
        mean_arr.data_ptr<float>(), var_arr.data_ptr<float>(),
        N, C, HW, total_units, use_vec4, (float)eps);
    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "batchnorm2d kernels launch failed: ", cudaGetErrorString(err));
    if (training) {
        running_mean.copy_(rm_c);
        running_var.copy_(rv_c);
    }
    return y;
}
"""

bn_ext = load_inline(
    name="cute_batchnorm2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["batchnorm2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Batch Normalization implemented with a single custom CUTE/CUDA kernel.
    """
    def __init__(self, num_features: int):
        super().__init__()
        self.num_features = num_features
        self.eps = 1e-5
        self.momentum = 0.1

        self.weight = nn.Parameter(torch.ones(num_features))
        self.bias = nn.Parameter(torch.zeros(num_features))

        self.register_buffer("running_mean", torch.zeros(num_features))
        self.register_buffer("running_var", torch.ones(num_features))
        self.register_buffer("num_batches_tracked", torch.tensor(0, dtype=torch.long))

        self._ext = bn_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if self.training:
            self.num_batches_tracked += 1

        return self._ext.batchnorm2d_forward(
            x,
            self.weight,
            self.bias,
            self.running_mean,
            self.running_var,
            self.training,
            float(self.momentum),
            float(self.eps),
        )

